\documentclass[border=1mm]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{patchplots}
\usepgfplotslibrary{colormaps}
\usepackage{tikz-3dplot}
\usetikzlibrary{patterns}

\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\def\cubecolor{deepskyblue}
	\def\arrowcolor{orangepeel}

	\pagestyle{empty}
	\begin{tikzpicture}[scale=1.5, rotate=0]

	\begin{axis}[
	scale=1.25,
	clip=false,
	view={110}{20},
	hide axis,
	xmin=-1,xmax=4,
	ymin=-1,ymax=4.75,
	zmin=-1,zmax=4,
	]

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	% Axes
	\def\axwidth{0.6}

	% Real side length
	% Should be from 0 to 2 (or 2.3)
	% Only to define proportions
	\def\lr{1}
	\def\lz{2}

	% Marks on axes 
	\def\mr{1} % x,y-tick
	\def\mz{2} % z-tick

	% Normal vector length
	\def\nl{1}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	% Axes

	% X
	\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:\lr,0,0);
	\draw[line width=\axwidth, -stealth] (axis cs:\lr,0,0) -- (axis cs:3,0,0)
	node[left, xshift=4pt, yshift=-3pt] {\scriptsize $x$}; 

	% Y
	\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:0,\lr,0);
	\draw[line width=\axwidth, -stealth] (axis cs:0,\lr,0) -- (axis cs:0,2.5,0)
	node[right, yshift=-2pt] {\scriptsize $y$};

	% Z
	\draw[line width=\axwidth/2, dashed] (axis cs:0,0,0) -- (axis cs:0,0,\lz);


	% Normal vectors
%	\node[circle, draw=none, fill=\arrowcolor, inner sep=0.75pt] at (axis cs:\lr/3,\lr/3,0) {};
%	\draw[\arrowcolor, line width=\axwidth, -latex] (axis cs:\lr/3,\lr/3,0) -- (axis cs:\lr/3,\lr/3,0-\nl) 
%	node[right, black] {\scriptsize $\mathbf{n}_2$};

	% Top 	
	\draw[draw=\cubecolor!50, line width=\axwidth/4, fill=none, fill opacity=0.5,
	shading = axis, left color=\cubecolor!10, right color=\cubecolor!90, shading angle=170]
	plot[domain=0:360, samples=360, variable=\t] (axis cs:{\lr*cos(\t)},{\lr*sin(\t)},{\lz});	
	% Front
	\draw[draw=\cubecolor!50, line width=\axwidth/4, fill=none, fill opacity=0.5,
	shading = axis, left color=\cubecolor!10, right color=\cubecolor!90, shading angle=0]
	plot[domain=-70:110, samples=360, variable=\t] (axis cs:{\lr*cos(\t)},{\lr*sin(\t)},{\lz}) --
	plot[domain=110:-70, samples=360, variable=\t] (axis cs:{\lr*cos(\t)},{\lr*sin(\t)},{0}) -- cycle;
	% Bottom
	\draw[draw=\cubecolor!80, line width=\axwidth/4, dashed]
	plot[domain=110:290, samples=360, variable=\t] (axis cs:{\lr*cos(\t)},{\lr*sin(\t)},{0});


	% Normal vectors
%	\node[circle, draw=none, fill=\arrowcolor, inner sep=0.75pt] at (axis cs:\lr/3,\lr/3,\lz) {};
%	\draw[\arrowcolor, line width=\axwidth, -latex] (axis cs:\lr/3,\lr/3,\lz) -- (axis cs:\lr/3,\lr/3,\lz+\nl) 
%	node[right, black] {\scriptsize $\mathbf{n}_1$};

	% Ticks

	\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[below, yshift=0pt]: \tiny $\mr$}] 
	at (axis cs:\lr,0,0) {};
	\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[below, yshift=0pt]: \tiny $\mr$}] 
	at (axis cs:0,\lr,0) {};
	\node[circle, draw=none, fill=black, inner sep=0.5pt, label={[left, xshift=1pt]: \tiny $\mz$}] 
	at (axis cs:0,0,\lz) {};

	% Z-cont.
	\draw[line width=\axwidth, -stealth] (axis cs:0,0,\lz) -- (axis cs:0,0,3)
	node[above] {\scriptsize $z$};  

	\end{axis}
	\end{tikzpicture}
\end{document}

